// QA orchestration only. Architecture and geometry are always generated by Rust.
import assert from 'node:assert/strict';
import {readFile, writeFile, rename} from 'node:fs/promises';
import {tsImport} from 'tsx/esm/api';

const contract = await tsImport(new URL('../../rust/bridge/housesContract.ts', import.meta.url).href, import.meta.url);
export const normalBudgetMs = 120000;
export const roundBudgets = {wasm_ms: 900000, native_ms: 450000,
  measured_wasm_ms: 688900, measured_native_ms: 309000,
  source: 'Addition20 release: WASM Node full parity; native release. Previous engine, not Chromium32.'};

export function qaConfig(changes = {}) {
  const overrides = {variant: null, footprint: null, roof: null, frame: null, infill: null,
    coating: null, cladding: null, floors: null, bodies: null, courtyard_ratio: null,
    overhang_m: null, roof_pitch_deg: null, site_slope_deg: null};
  const config = {schema_version: contract.HOUSE_SCHEMA, seed: '42', pack: 'EUR-MED', recipe: null,
    mode: 'historical_inspired', era: 'any', allow_late: false, count: 10,
    size: 1, variation: .65, wealth: .5, orientation_deg: 0, ...changes,
    overrides: {...overrides, ...changes.overrides}};
  contract.validateHouseConfig(config);
  return config;
}

export function replayUrl(base, config) {
  contract.validateHouseConfig(config);
  const view = {mode: 'roof', level: 0, graph: false, dimensions: false};
  const data = {version: 1, generator_version: contract.HOUSE_GENERATOR, config, view};
  const encoded = Buffer.from(JSON.stringify(data), 'utf8').toString('base64url');
  assert(!encoded.includes('='));
  const url = new URL(base); url.searchParams.set('houses', 'v1'); url.searchParams.set('replay', encoded);
  assert.deepEqual(JSON.parse(Buffer.from(url.searchParams.get('replay'), 'base64url')), data);
  return url.href;
}

export async function saveReport(path, report) {
  await writeFile(`${path}.tmp`, JSON.stringify(report, null, 2));
  await rename(`${path}.tmp`, path);
}

export async function readMeasuredBudgets(path, expectedConfig) {
  if (!path) return {};
  const entries = JSON.parse(await readFile(path, 'utf8'));
  assert(entries && typeof entries === 'object' && !Array.isArray(entries));
  for (const [id, entry] of Object.entries(entries)) {
    assert(Number.isSafeInteger(entry.timeout_ms) && entry.timeout_ms > 0, `${id}: invalid timeout_ms`);
    assert(Number.isFinite(entry.measured_ms) && entry.measured_ms > 0, `${id}: missing measured_ms`);
    assert(typeof entry.source === 'string' && entry.source.trim(), `${id}: missing measurement source`);
    assert.deepEqual(entry.config, expectedConfig(id), `${id}: measurement must use the same entire batch config`);
  }
  return entries;
}

export function classifyLine(message) {
  if (/^\d+ unités · réussi$/.test(message)) return {status: 'success', message};
  const code = message.match(/^\[(\w+)\]/)?.[1];
  if (code === 'wasm_runtime' || code === 'worker_failed') return {status: 'browserError', code, message};
  if (code) return {status: 'rustError', code, message};
  if (message.startsWith('Worker maisons :')) return {status: 'browserError', message};
  if (message === 'Requête remplacée.') return {status: 'cancelled', message};
  if (/64\s*(Mio|Mo)|plafond.*réponse/i.test(message)) return {status: 'contractError', message};
  return {status: 'unclassified', message};
}

export function errorIssue(error, phase) {
  if (error?.qaIssue) return {...error.qaIssue, phase};
  return {status: error?.name === 'TimeoutError' ? 'timeoutQA' : 'browserError', phase,
    message: error instanceof Error ? error.message : String(error)};
}

export async function installWorkerTrace(surface) {
  await surface.addInitScript(() => {
    window.houseQaTrace = {requests: [], responses: [], terminated: []};
    window.houseRequests = [];
    const NativeWorker = window.Worker;
    if (!NativeWorker) return;
    let nextId = 0;
    window.Worker = class extends NativeWorker {
      constructor(...args) {
        super(...args); this.qaWorkerId = ++nextId;
        this.addEventListener('message', ({data}) => window.houseQaTrace.responses.push({worker: this.qaWorkerId,
          at_ms: performance.now(), ticket: data.ticket, kind: data.kind, fatal: data.fatal ?? false, error: data.error ?? null}));
      }
      postMessage(data, ...args) {
        const config = data.config ? JSON.parse(JSON.stringify(data.config)) : null;
        window.houseQaTrace.requests.push({worker: this.qaWorkerId, at_ms: performance.now(),
          ticket: data.ticket, kind: data.kind, config});
        if (config) window.houseRequests.push(config);
        return super.postMessage(data, ...args);
      }
      terminate() {
        window.houseQaTrace.terminated.push({worker: this.qaWorkerId, at_ms: performance.now()});
        return super.terminate();
      }
    };
  });
}

export async function checkReplayBatch(page, batch, config) {
  assert.equal(await page.locator('#replay-warning').isVisible(), false, 'Generator replay warning');
  assert.deepEqual(batch.settings, config, 'The requested replay produced the exported batch');
  const trace = await page.evaluate(() => window.houseQaTrace);
  const generated = trace.requests.filter(request => request.kind === 'generate');
  assert.equal(generated.length, 1, 'A replay boot generates the requested batch once');
  assert.deepEqual(generated[0].config, config);
  return trace;
}
